const optGroupsToObject = (groups: NodeListOf<HTMLOptGroupElement>) => {
  return groups.values()
      .map(
          group => ({[group.label]: group.querySelectorAll('option').values().map(node => node.textContent).toArray()}))
      .toArray();
};

describeWithEnvironment('NetworkThrottlingSelector', () => {
  it('renders the global throttling variant', async () => {
    const selectElement = document.createElement('select');
    const widget = new MobileThrottling.NetworkThrottlingSelector.NetworkThrottlingSelect(selectElement);
    widget.variant = MobileThrottling.NetworkThrottlingSelector.NetworkThrottlingSelect.Variant.GLOBAL_CONDITIONS;

    await doubleRaf();

    const optgroups = selectElement.querySelectorAll('optgroup');
    assert.deepEqual(optGroupsToObject(optgroups), [
      {
        Disabled: [
          'No throttling',
        ],
      },
      {
        Presets: [
          'Fast 4G',
          'Slow 4G',
          '3G',
          'Offline',
        ],
      },
      {
        Custom: [
          'Add…',
        ],
      },
    ]);
  });

  it('renders the individual request variant', async () => {
    const selectElement = document.createElement('select');
    const widget = new MobileThrottling.NetworkThrottlingSelector.NetworkThrottlingSelect(selectElement);
    widget.variant =
        MobileThrottling.NetworkThrottlingSelector.NetworkThrottlingSelect.Variant.INDIVIDUAL_REQUEST_CONDITIONS;

    await doubleRaf();

    const optgroups = selectElement.querySelectorAll('optgroup');
    assert.deepEqual(optGroupsToObject(optgroups), [
      {
        Blocking: [
          'Block',
        ],
      },
      {
        Presets: [
          'Fast 4G',
          'Slow 4G',
          '3G',
        ],
      },
      {
        Custom: [
          'Add…',
        ],
      },
    ]);
  });

  it('sets the current conditions', async () => {
    const selectElement = document.createElement('select');
    const widget = new MobileThrottling.NetworkThrottlingSelector.NetworkThrottlingSelect(selectElement);
    widget.variant = MobileThrottling.NetworkThrottlingSelector.NetworkThrottlingSelect.Variant.GLOBAL_CONDITIONS;
    widget.currentConditions = SDK.NetworkManager.Slow3GConditions;

    await doubleRaf();

    assert.strictEqual(selectElement.value, '3G');
  });

  it('observes change events', async () => {
    const selectElement = document.createElement('select');
    const widget = new MobileThrottling.NetworkThrottlingSelector.NetworkThrottlingSelect(selectElement);
    widget.variant = MobileThrottling.NetworkThrottlingSelector.NetworkThrottlingSelect.Variant.GLOBAL_CONDITIONS;

    await doubleRaf();

    const onConditionsChanged = sinon.stub();
    selectElement.addEventListener('ConditionsChanged', onConditionsChanged);

    selectElement.selectedIndex = 2;
    selectElement.dispatchEvent(new Event('change'));

    sinon.assert.calledOnce(onConditionsChanged);
    const event = onConditionsChanged.firstCall.args[0] as CustomEvent;
    assert.strictEqual(event.detail, SDK.NetworkManager.Slow4GConditions);
  });
});

describeWithEnvironment('createForGlobalConditions CrUX integration', () => {
  it('shows recommended label when CrUX data provides RTT', async () => {
    const cruxManager = CrUXManager.CrUXManager.instance({forceNew: true});
    sinon.stub(cruxManager, 'getSelectedFieldMetricData').returns({
      percentiles: {p75: '150'},
      histogram: [],
    });

    const container = document.createElement('div');
    renderElementIntoDOM(container);
    const select = MobileThrottling.NetworkThrottlingSelector.NetworkThrottlingSelect.createForGlobalConditions(
        container, 'Network throttling');
    assert.isNotNull(select.recommendedConditions);
    assert.strictEqual(select.recommendedConditions, SDK.NetworkManager.Slow4GConditions);

    await doubleRaf();

    // Verify the recommended label appears in the rendered DOM.
    const options = select.contentElement.querySelectorAll('option');
    const slow4gOption = Array.from(options).find(opt => opt.textContent?.includes('Slow 4G'));
    assert.isDefined(slow4gOption);
    assert.include(slow4gOption.textContent, 'recommended');
  });

  it('updates recommendation when CrUX field data changes', () => {
    const cruxManager = CrUXManager.CrUXManager.instance({forceNew: true});
    const stub = sinon.stub(cruxManager, 'getSelectedFieldMetricData').returns(undefined);

    const container = document.createElement('div');
    renderElementIntoDOM(container);
    const select = MobileThrottling.NetworkThrottlingSelector.NetworkThrottlingSelect.createForGlobalConditions(
        container, 'Network throttling');
    assert.isNull(select.recommendedConditions);

    // Simulate CrUX data becoming available.
    stub.returns({
      percentiles: {p75: '150'},
      histogram: [],
    });
    cruxManager.dispatchEventToListeners(CrUXManager.Events.FIELD_DATA_CHANGED, undefined);

    assert.isNotNull(select.recommendedConditions);
    assert.strictEqual(select.recommendedConditions, SDK.NetworkManager.Slow4GConditions);
  });

  it('clears recommendation when CrUX data is removed', () => {
    const cruxManager = CrUXManager.CrUXManager.instance({forceNew: true});
    const stub = sinon.stub(cruxManager, 'getSelectedFieldMetricData').returns({
      percentiles: {p75: '150'},
      histogram: [],
    });

    const container = document.createElement('div');
    renderElementIntoDOM(container);
    const select = MobileThrottling.NetworkThrottlingSelector.NetworkThrottlingSelect.createForGlobalConditions(
        container, 'Network throttling');
    assert.isNotNull(select.recommendedConditions);

    // Simulate CrUX data being removed.
    stub.returns(undefined);
    cruxManager.dispatchEventToListeners(CrUXManager.Events.FIELD_DATA_CHANGED, undefined);

    assert.isNull(select.recommendedConditions);
  });
});

describeWithEnvironment('NetworkThrottlingSelect listeners', () => {
  const {NetworkThrottlingSelect} = MobileThrottling.NetworkThrottlingSelector;
  let multitargetNetworkManager: SDK.NetworkManager.MultitargetNetworkManager;
  let cruxManager: CrUXManager.CrUXManager;
  let getSelectedFieldMetricData: sinon.SinonStub;

  beforeEach(() => {
    multitargetNetworkManager = SDK.NetworkManager.MultitargetNetworkManager.instance({forceNew: true});
    MobileThrottling.ThrottlingManager.ThrottlingManager.instance({forceNew: true});
    cruxManager = CrUXManager.CrUXManager.instance({forceNew: true});
    getSelectedFieldMetricData = sinon.stub(cruxManager, 'getSelectedFieldMetricData').returns(undefined);
  });

  function listensToCustomConditions(select: MobileThrottling.NetworkThrottlingSelector.NetworkThrottlingSelect):
      boolean {
    const {listeners} = Common.Settings.Settings.instance().eventTargetForTest;
    return [...listeners?.get('custom-network-conditions') ?? []].some(({thisObject}) => thisObject === select);
  }

  function changeGlobalConditionsAndFieldData(): void {
    multitargetNetworkManager.setNetworkConditions(SDK.NetworkManager.Slow3GConditions);
    getSelectedFieldMetricData.returns({percentiles: {p75: '150'}, histogram: []});
    cruxManager.dispatchEventToListeners(CrUXManager.Events.FIELD_DATA_CHANGED, undefined);
  }

  it('only tracks the global conditions while shown', () => {
    const container = document.createElement('div');
    renderElementIntoDOM(container);
    const select = NetworkThrottlingSelect.createForGlobalConditions(container, 'Network throttling');
    assert.isTrue(listensToCustomConditions(select));
    assert.isTrue(cruxManager.hasEventListeners(CrUXManager.Events.FIELD_DATA_CHANGED));

    select.detach();
    assert.isFalse(listensToCustomConditions(select));
    assert.isFalse(cruxManager.hasEventListeners(CrUXManager.Events.FIELD_DATA_CHANGED));
    changeGlobalConditionsAndFieldData();
    assert.strictEqual(select.currentConditions, SDK.NetworkManager.NoThrottlingConditions);
    assert.isNull(select.recommendedConditions);

    // The changes made while the select was hidden are picked up when it is shown again.
    select.show(container);
    assert.strictEqual(select.currentConditions, SDK.NetworkManager.Slow3GConditions);
    assert.strictEqual(select.recommendedConditions, SDK.NetworkManager.Slow4GConditions);
    multitargetNetworkManager.setNetworkConditions(SDK.NetworkManager.Fast4GConditions);
    assert.strictEqual(select.currentConditions, SDK.NetworkManager.Fast4GConditions);
  });

  it('stops tracking the global conditions when its element is removed', async () => {
    // This is how the `widget()` directive instantiates the select, e.g. in the device toolbar.
    const selectElement = document.createElement('select');
    UI.Widget.registerWidgetConfig(selectElement,
                                   UI.Widget.widgetConfig(NetworkThrottlingSelect, {bindToGlobalConditions: true}));
    renderElementIntoDOM(selectElement);
    const select = UI.Widget.Widget.get(selectElement);
    assert.instanceOf(select, NetworkThrottlingSelect);
    assert.isTrue(listensToCustomConditions(select));
    assert.isTrue(cruxManager.hasEventListeners(CrUXManager.Events.FIELD_DATA_CHANGED));

    selectElement.remove();
    // The widget is detached asynchronously after its element was disconnected.
    await new Promise(resolve => setTimeout(resolve, 0));

    assert.isFalse(listensToCustomConditions(select));
    assert.isFalse(cruxManager.hasEventListeners(CrUXManager.Events.FIELD_DATA_CHANGED));
    changeGlobalConditionsAndFieldData();
    assert.strictEqual(select.currentConditions, SDK.NetworkManager.NoThrottlingConditions);
    assert.isNull(select.recommendedConditions);
  });

  it('only re-renders on custom conditions changes while shown', async () => {
    const view = sinon.stub<Parameters<MobileThrottling.NetworkThrottlingSelector.ViewFunction>, void>();
    const select =
        new NetworkThrottlingSelect(document.createElement('select'), {}, Common.Settings.Settings.instance(), view);
    renderElementIntoDOM(select);
    await UI.Widget.Widget.allUpdatesComplete;
    const customConditions: SDK.NetworkManager.Conditions = {
      key: 'USER_CUSTOM_SETTING_1',
      title: 'Custom conditions',
      download: 1000,
      upload: 1000,
      latency: 100,
    };

    select.detach();
    view.resetHistory();
    SDK.NetworkManager.customUserNetworkConditionsSetting(Common.Settings.Settings.instance()).set([customConditions]);
    await UI.Widget.Widget.allUpdatesComplete;
    sinon.assert.notCalled(view);

    renderElementIntoDOM(select);
    await UI.Widget.Widget.allUpdatesComplete;
    assert.deepEqual(view.lastCall.args[0].customConditionsGroup.items, [customConditions]);
  });
});

describe('NetworkThrottlingSelect getRecommendedNetworkConditions', () => {
  it('returns null when RTT data is missing', () => {
    const result = MobileThrottling.NetworkThrottlingSelector.getRecommendedNetworkConditions(
        undefined,
    );

    assert.isNull(result);
  });

  it('returns a matching preset when RTT data is available', () => {
    const result = MobileThrottling.NetworkThrottlingSelector.getRecommendedNetworkConditions(
        {
          percentiles: {p75: '150'},
        },
    );

    assert.strictEqual(result, SDK.NetworkManager.Slow4GConditions);
  });

  it('returns null when RTT data is invalid or too low', () => {
    const invalidResult = MobileThrottling.NetworkThrottlingSelector.getRecommendedNetworkConditions(
        {
          percentiles: {p75: 'not-a-number'},
        },
    );
    assert.isNull(invalidResult);

    const tooLowResult = MobileThrottling.NetworkThrottlingSelector.getRecommendedNetworkConditions(
        {
          percentiles: {p75: '10'},
        },
    );
    assert.isNull(tooLowResult);
  });
});
